export interface Driver {
  id: string;
  name: string;
  number: string;
  nationality: string;
  teamId: string;
  image?: string;
  cutout?: string;
}

export interface Team {
  id: string;
  name: string;
  color: string;
  car?: string;
  logo?: string;
  badge?: string;
  clearart?: string;
  class?: string;
}

export interface Race {
  id: string;
  name: string;
  enName?: string;
  location: string;
  enLocation?: string;
  date: string;
  circuit: string;
  status: 'upcoming' | 'completed' | 'cancelled';
  winner?: string;
}

export interface StandingItem {
  position: number;
  name: string;
  points: number;
  team?: string;
  extra?: string;
}

export interface CategoryStandings {
  drivers?: StandingItem[];
  constructors?: StandingItem[];
  teams?: StandingItem[];
}

export interface RuleSection {
  title: string;
  enTitle?: string;
  body: string;
  enBody?: string;
}

export interface Category {
  id: string;
  name: string;
  fullName: string;
  enFullName?: string;
  description: string;
  enDescription?: string;
  longDescription: string;
  enLongDescription?: string;
  // Explicação séria e detalhada de formato de fim de semana, pontuação e
  // regulamento técnico - o que aparece no modal "Regras e Formato". Distinto
  // do longDescription (resumo curto usado na aba Visão Geral).
  rulesFormat?: RuleSection[];
  icon: string;
  teams: Team[];
  drivers: Driver[];
  calendar: Race[];
  standings?: CategoryStandings;
}

